public class TernarySearch {
    // Discrete peak via slope binary search (preferred for arrays).
    public int peakIndex(int[] arr) {
        int lo = 0, hi = arr.length - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (arr[mid] < arr[mid + 1]) {
                lo = mid + 1; // still climbing → peak to the right
            } else {
                hi = mid;     // descending → peak at mid or left
            }
        }
        return lo;
    }

    // Classic ternary search on a real unimodal function (maximize).
    public double argmax(java.util.function.DoubleUnaryOperator f, double lo, double hi) {
        for (int iter = 0; iter < 200; iter++) {
            double m1 = lo + (hi - lo) / 3.0;
            double m2 = hi - (hi - lo) / 3.0;
            if (f.applyAsDouble(m1) < f.applyAsDouble(m2)) {
                lo = m1;
            } else {
                hi = m2;
            }
        }
        return (lo + hi) / 2.0;
    }

    public static void main(String[] args) {
        TernarySearch ts = new TernarySearch();
        System.out.println(ts.peakIndex(new int[]{1, 3, 8, 12, 4, 2}));
        System.out.printf("%.4f%n", ts.argmax(x -> -(x - 2) * (x - 2) + 5, 0, 5));
    }
}

