from typing import Callable


def peak_index(arr: list[int]) -> int:
    lo, hi = 0, len(arr) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < arr[mid + 1]:
            lo = mid + 1   # still climbing -> peak to the right
        else:
            hi = mid        # descending -> peak at mid or left
    return lo


def argmax(f: Callable[[float], float], lo: float, hi: float) -> float:
    for _ in range(200):
        m1 = lo + (hi - lo) / 3.0
        m2 = hi - (hi - lo) / 3.0
        if f(m1) < f(m2):
            lo = m1
        else:
            hi = m2
    return (lo + hi) / 2.0


if __name__ == "__main__":
    print(peak_index([1, 3, 8, 12, 4, 2]))
    print(round(argmax(lambda x: -(x - 2) ** 2 + 5, 0, 5), 4))

